Invoke-WebRequest -Uri "https://github.com/gradle/gradle/raw/v8.10.2/gradle/wrapper/gradle-wrapper.jar" -OutFile (Join-Path $wdir "gradle-wrapper.jar")
"writing gradlew.bat..."
